// Animal-world concept glossary (Hebrew). A page per term and per well-known species, each linked to the lesson
// that teaches it. Species already covered by /animals/* (great white shark, octopus, dolphin, blue whale, frog,
// snake, spider, bee, hoopoe…) are not repeated here; these pages add other species and the key terms.
// Numbers checked against two sources (2026-10-30); approximate where sources differ. Safety: never touch wild
// snakes, spiders, scorpions or injured animals; after a bite or sting call מד״א (101).
const q = (question, right, wrong, exp) => ({ q: question, options: [right, ...wrong], exp })
// kind 'term' → "מה זה …?"; kind 'animal' → "… — עובדות לילדים".
const concept = ({ kind = 'animal', ...c }) => ({
  title: kind === 'term' ? `מה זה ${c.term}?` : `${c.term}: עובדות לילדים`,
  seoTitle: kind === 'term' ? `מה זה ${c.term}? הסבר פשוט לילדים, דוגמאות וחידון` : `${c.term} — עובדות לילדים, תמונה במילים וחידון`,
  // The short definition plus a note, trimmed to what fits a search snippet (≤ 168 characters).
  seoDesc: c.seoDesc || [`${c.short} הסבר לילדים עם דוגמאות וחידון.`, `${c.short} עם חידון.`, c.short].find(s => s.length <= 168),
  ...c
})

